const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const W=1000,H=640,player={x:500,y:588,r:12,speed:2.55,face:0};
const residents=[{x:255,y:220,name:'Mara',color:'#f0b887',rescued:false,following:false},{x:735,y:220,name:'Theo',color:'#9cc2d3',rescued:false,following:false},{x:260,y:440,name:'June',color:'#d2a7c7',rescued:false,following:false},{x:740,y:440,name:'Eli',color:'#e4d07b',rescued:false,following:false}];
const walls=[
 {x:130,y:105,w:740,h:16},{x:130,y:105,w:16,h:435},{x:854,y:105,w:16,h:435},
 {x:130,y:524,w:330,h:16},{x:540,y:524,w:330,h:16},
 {x:490,y:524,w:20,h:16},
 {x:495,y:105,w:10,h:150},{x:495,y:315,w:10,h:209},
 {x:146,y:305,w:255,h:10},{x:465,y:305,w:30,h:10},{x:505,y:305,w:30,h:10},{x:600,y:305,w:254,h:10},
 {x:395,y:115,w:10,h:180},{x:595,y:115,w:10,h:180},
 {x:395,y:315,w:10,h:209},{x:595,y:315,w:10,h:209}
];
let running=false,won=false,last=0,elapsed=0,risk=0,keys={},clickTarget=null,messageTimer=0,calmCooldown=0,showToast='';
const el=id=>document.getElementById(id);
function start(){if(won){reset()}running=true;el('overlay').style.display='none';el('statusLabel').textContent='ACTIVE';last=performance.now();requestAnimationFrame(loop)}
function reset(){player.x=500;player.y=588;residents.forEach(r=>{r.rescued=false;r.following=false});running=false;won=false;elapsed=0;risk=0;clickTarget=null;updateUI()}
el('startBtn').addEventListener('click',start);el('restartBtn').addEventListener('click',()=>{reset();el('statusLabel').textContent='STANDBY';el('modalTitle').innerHTML='Get everyone<br>out safely.';el('modalText').textContent='Lead a 10-officer rescue unit through the house. Find the residents, keep them calm, and escort everyone to the safe exit.';el('startBtn').textContent='BEGIN OPERATION  →';el('overlay').style.display='grid'});
function updateUI(){let count=residents.filter(r=>r.rescued).length;el('savedCount').textContent=count;el('saveBar').style.width=(count*25)+'%';el('riskText').textContent=Math.floor(risk)+'%';el('riskBar').style.width=risk+'%';el('obj1').classList.toggle('done',player.y<540);el('obj2').classList.toggle('done',count>0);el('obj3').classList.toggle('done',won)}
function toast(t){showToast=t;el('message').textContent=t;el('message').classList.add('show');clearTimeout(messageTimer);messageTimer=setTimeout(()=>el('message').classList.remove('show'),1900)}
function calm(){if(!running||calmCooldown>0)return;risk=Math.max(0,risk-17);calmCooldown=3.5;toast('Unit calm pulse — situation de-escalated');updateUI()}
function rescue(){if(!running)return;let r=residents.find(a=>!a.rescued&&!a.following&&Math.hypot(a.x-player.x,a.y-player.y)<46);if(r){r.following=true;risk=Math.max(0,risk-5);toast(r.name+' is with the unit — guide them to the exit');updateUI()}else if(residents.some(a=>a.following)&&Math.hypot(500-player.x,560-player.y)<48){let following=residents.filter(a=>a.following);following.forEach(a=>{a.following=false;a.rescued=true});toast(following.length===1?following[0].name+' safely evacuated':following.length+' residents safely evacuated');updateUI();checkWin()}else{toast('Move close to a resident or the marked exit')}}
function checkWin(){if(residents.every(r=>r.rescued)){won=true;running=false;el('statusLabel').textContent='MISSION COMPLETE';el('modalTitle').innerHTML='Everyone is<br>safe.';el('modalText').textContent='Excellent work. All four residents made it out, and your 10-officer unit returned intact.';el('startBtn').textContent='PLAY AGAIN  →';el('overlay').style.display='grid'}}
function nearestAction(){let r=residents.find(a=>!a.rescued&&!a.following&&Math.hypot(a.x-player.x,a.y-player.y)<46);return r?'E  RESCUE '+r.name:residents.some(a=>a.following)&&Math.hypot(500-player.x,560-player.y)<48?'E  EVACUATE':'E  RESCUE'}
window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();keys[k]=true;if(k==='e')rescue();if(k===' ')calm();if(k==='enter'&&!running)start()});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
canvas.addEventListener('pointerdown',e=>{if(!running)return;let rect=canvas.getBoundingClientRect(),x=(e.clientX-rect.left)*W/rect.width,y=(e.clientY-rect.top)*H/rect.height;let r=residents.find(a=>!a.rescued&&!a.following&&Math.hypot(a.x-x,a.y-y)<50);if(r){clickTarget={x:r.x,y:r.y};return}if(Math.hypot(500-x,560-y)<40&&residents.some(a=>a.following)){clickTarget={x:500,y:560};return}clickTarget={x,y}});
document.querySelectorAll('[data-dir]').forEach(b=>{let d=b.dataset.dir;b.addEventListener('pointerdown',e=>{e.preventDefault();keys['touch'+d]=true;b.setPointerCapture(e.pointerId)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>keys['touch'+d]=false))});el('touchRescue').addEventListener('pointerdown',e=>{e.preventDefault();rescue()});el('touchCalm').addEventListener('pointerdown',e=>{e.preventDefault();calm()});
function blocked(x,y){if(x<115||x>885||y<85||y>610)return true;for(const w of walls){if(x+player.r>w.x&&x-player.r<w.x+w.w&&y+player.r>w.y&&y-player.r<w.y+w.h)return true}return false}

function update(dt){if(!running)return;elapsed+=dt;calmCooldown=Math.max(0,calmCooldown-dt);risk=Math.min(100,risk+dt*1.35);let dx=0,dy=0;if(keys.w||keys.arrowup||keys.touchup)dy--;if(keys.s||keys.arrowdown||keys.touchdown)dy++;if(keys.a||keys.arrowleft||keys.touchleft)dx--;if(keys.d||keys.arrowright||keys.touchright)dx++;if(clickTarget){let vx=clickTarget.x-player.x,vy=clickTarget.y-player.y,dist=Math.hypot(vx,vy);if(dist<8)clickTarget=null;else{dx+=vx/dist;dy+=vy/dist}}let len=Math.hypot(dx,dy);if(len){dx/=len;dy/=len;player.face=Math.atan2(dy,dx);let nx=player.x+dx*player.speed,ny=player.y+dy*player.speed;if(!blocked(nx,player.y))player.x=nx;else clickTarget=null;if(!blocked(player.x,ny))player.y=ny;else clickTarget=null}
 for(let i=0;i<residents.length;i++){let r=residents[i];if(!r.following)continue;let tx=player.x-(i%2?25:-25),ty=player.y+22+Math.floor(i/2)*15, vx=tx-r.x,vy=ty-r.y,d=Math.hypot(vx,vy);if(d>4){let speed=Math.min(2,d);let nx=r.x+vx/d*speed,ny=r.y+vy/d*speed;if(!walls.some(w=>nx+9>w.x&&nx-9<w.x+w.w&&ny+9>w.y&&ny-9<w.y+w.h)){r.x=nx;r.y=ny}}}
 if(risk>=100){running=false;el('statusLabel').textContent='RESET REQUIRED';el('modalTitle').innerHTML='Take a breath.<br>Try again.';el('modalText').textContent='The situation escalated before everyone was evacuated. Use calm pulses with SPACE, stay together, and keep moving.';el('startBtn').textContent='REDEPLOY UNIT  →';el('overlay').style.display='grid'}updateUI()}
function rr(x,y,w,h,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
function draw(){ctx.clearRect(0,0,W,H);
 // exterior yard
 ctx.fillStyle='#1c2921';ctx.fillRect(0,0,W,H);ctx.fillStyle='#26352a';for(let i=0;i<80;i++){let x=(i*173+29)%W,y=(i*97+19)%H;if(y>75&&y<560&&(x<120||x>880||y<85||y>550)){ctx.globalAlpha=.17;ctx.beginPath();ctx.arc(x,y,1+(i%3),0,Math.PI*2);ctx.fillStyle='#9cb27d';ctx.fill()} }ctx.globalAlpha=1;
 // path and house floor
 ctx.fillStyle='#3b493c';ctx.fillRect(450,540,100,100);ctx.fillStyle='#a1a982';ctx.globalAlpha=.14;ctx.fillRect(468,540,64,100);ctx.globalAlpha=1;
 rr(120,90,760,450,8,'#3b463b');rr(132,102,736,426,2,'#b4a78b');rr(144,114,712,410,0,'#887d68');
 // room floors
 ctx.fillStyle='#b8aa8a';ctx.fillRect(146,116,347,188);ctx.fillRect(503,116,351,188);ctx.fillRect(146,316,347,206);ctx.fillRect(503,316,351,206);
 // floor plank subtle streaks
 ctx.strokeStyle='#756f5e';ctx.globalAlpha=.18;ctx.lineWidth=1;for(let y=125;y<520;y+=20){ctx.beginPath();ctx.moveTo(148,y);ctx.lineTo(492,y);ctx.stroke();ctx.beginPath();ctx.moveTo(506,y);ctx.lineTo(852,y);ctx.stroke()}for(let x=165;x<850;x+=38){ctx.beginPath();ctx.moveTo(x,116);ctx.lineTo(x,304);ctx.stroke();ctx.beginPath();ctx.moveTo(x,316);ctx.lineTo(x,522);ctx.stroke()}ctx.globalAlpha=1;
 // rugs
 rr(192,147,158,105,4,'#a78061');rr(208,160,126,78,2,'#c4a27d');rr(640,147,166,104,4,'#668176');rr(653,160,140,78,2,'#8fa698');rr(190,363,170,110,4,'#667b65');rr(203,376,144,84,2,'#96a287');rr(640,363,165,110,4,'#a77b60');rr(653,376,139,84,2,'#c4a083');
 // furniture beds and couches
 rr(160,124,80,40,5,'#625649');rr(165,128,70,17,5,'#d7cdb5');rr(165,149,70,11,3,'#9b8b73');rr(410,160,54,94,5,'#68594b');rr(416,165,42,38,5,'#d4c7ab');rr(416,209,42,40,4,'#a28c6e');rr(705,124,98,36,5,'#6f6354');rr(710,128,88,22,4,'#bea98c');rr(553,174,37,74,4,'#635848');rr(557,180,29,60,3,'#a9987d');rr(164,410,74,80,5,'#685747');rr(169,415,64,35,4,'#d3c8af');rr(169,454,64,31,3,'#9a876b');rr(391,390,77,66,5,'#6d6051');rr(397,396,65,21,4,'#d3c6a9');rr(397,423,65,27,3,'#a18e70');rr(765,394,64,88,5,'#67594b');rr(770,399,54,30,4,'#d6c9ad');rr(770,435,54,42,3,'#9c886b');rr(550,408,62,70,4,'#6b604f');rr(555,413,52,60,3,'#af9c7d');
 // tables
 rr(312,126,53,43,4,'#77644d');rr(322,135,33,25,3,'#c0a37a');rr(624,260,48,30,4,'#77644d');rr(632,265,32,20,3,'#c0a37a');rr(300,480,55,31,4,'#77644d');rr(308,485,39,21,3,'#c0a37a');
 // doors and wall strokes
 ctx.fillStyle='#333e34';ctx.fillRect(120,90,760,14);ctx.fillRect(120,90,14,450);ctx.fillRect(866,90,14,450);ctx.fillRect(120,526,335,14);ctx.fillRect(545,526,335,14);
 ctx.fillRect(495,90,10,165);ctx.fillRect(495,315,10,211);ctx.fillRect(140,305,260,10);ctx.fillRect(460,305,40,10);ctx.fillRect(500,305,40,10);ctx.fillRect(600,305,260,10);ctx.fillRect(395,110,10,195);ctx.fillRect(595,110,10,195);ctx.fillRect(395,315,10,211);ctx.fillRect(595,315,10,211);
 // doors, purposeful gaps
 ctx.fillStyle='#d3b88b';ctx.fillRect(455,526,90,14);ctx.fillRect(496,255,8,50);ctx.fillRect(460,303,35,4);ctx.fillRect(505,303,35,4);ctx.fillRect(395,214,5,45);ctx.fillRect(595,214,5,45);ctx.fillRect(395,415,5,45);ctx.fillRect(595,415,5,45);
 // windows
 for(let x of [190,265,665,740]){ctx.fillStyle='#96b9ac';ctx.fillRect(x,92,42,7);ctx.fillStyle='#d7cfb2';ctx.fillRect(x+19,91,3,10)}
 // room labels
 ctx.font='800 10px system-ui';ctx.fillStyle='#615a4c';ctx.globalAlpha=.78;ctx.fillText('LIVING ROOM',154,294);ctx.fillText('KITCHEN',700,294);ctx.fillText('BEDROOM',154,515);ctx.fillText('DEN',700,515);ctx.globalAlpha=1;
 // small plants
 for(let [x,y] of [[370,137],[830,185],[374,496],[618,132],[828,486]]){ctx.fillStyle='#425f47';ctx.beginPath();ctx.arc(x,y,11,0,Math.PI*2);ctx.fill();ctx.fillStyle='#779368';ctx.beginPath();ctx.arc(x-3,y-3,5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#a08b69';ctx.fillRect(x-6,y+7,12,5)}

 // exit marker
 ctx.save();ctx.translate(500,560);ctx.fillStyle='#c8f169';ctx.globalAlpha=.22;ctx.beginPath();ctx.arc(0,0,34,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.strokeStyle='#c8f169';ctx.lineWidth=2;ctx.setLineDash([5,4]);ctx.beginPath();ctx.arc(0,0,25,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#c8f169';ctx.font='900 9px system-ui';ctx.textAlign='center';ctx.fillText('SAFE EXIT',0,4);ctx.restore();
 // residents
 for(let r of residents){if(r.rescued)continue;let pulse=1+Math.sin(performance.now()/260+r.x)*.06;ctx.save();ctx.translate(r.x,r.y);ctx.scale(pulse,pulse);if(!r.following){ctx.globalAlpha=.22;ctx.fillStyle='#f2b756';ctx.beginPath();ctx.arc(0,0,25+Math.sin(performance.now()/230)*2,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}ctx.fillStyle='#242923';ctx.beginPath();ctx.ellipse(0,13,11,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=r.color;ctx.beginPath();ctx.arc(0,0,9,0,Math.PI*2);ctx.fill();ctx.fillStyle='#48332d';ctx.beginPath();ctx.arc(-2,-3,8,Math.PI,Math.PI*2);ctx.fill();ctx.fillStyle='#24231e';ctx.beginPath();ctx.arc(3,0,1.1,0,Math.PI*2);ctx.fill();if(!r.following){ctx.fillStyle='#342c22';ctx.font='700 9px system-ui';ctx.textAlign='center';ctx.fillText(r.name,0,-15)}else{ctx.fillStyle='#c8f169';ctx.font='900 8px system-ui';ctx.textAlign='center';ctx.fillText('WITH UNIT',0,-15)}ctx.restore()}
 // officers, 10 small coordinated figures follow player in echelon
 for(let i=9;i>=0;i--){let a=player.face+Math.PI;let row=Math.floor(i/2)+1, side=i%2===0?-1:1;let tx=player.x+Math.cos(a)*row*17+Math.cos(a+Math.PI/2)*side*10,ty=player.y+Math.sin(a)*row*17+Math.sin(a+Math.PI/2)*side*10;ctx.fillStyle='#141b17';ctx.beginPath();ctx.ellipse(tx,ty+7,7,3.8,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#3d5147';ctx.beginPath();ctx.arc(tx,ty,5.6,0,Math.PI*2);ctx.fill();ctx.fillStyle='#87977e';ctx.beginPath();ctx.arc(tx,ty-1,4,0,Math.PI*2);ctx.fill();ctx.fillStyle='#222b25';ctx.fillRect(tx-2,ty-6,5,4);ctx.fillStyle='#c8f169';ctx.fillRect(tx-1,ty-1,2,2)}
 // leader
 ctx.save();ctx.translate(player.x,player.y);ctx.rotate(player.face);ctx.fillStyle='#131a16';ctx.beginPath();ctx.ellipse(0,9,10,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#c8f169';ctx.beginPath();ctx.arc(0,0,10,0,Math.PI*2);ctx.fill();ctx.fillStyle='#29352c';ctx.beginPath();ctx.arc(1,-2,7,0,Math.PI*2);ctx.fill();ctx.fillStyle='#eef1d9';ctx.fillRect(4,-2,5,3);ctx.restore();
 // click marker
 if(clickTarget&&running){ctx.strokeStyle='#c8f169';ctx.globalAlpha=.65;ctx.lineWidth=2;ctx.beginPath();ctx.arc(clickTarget.x,clickTarget.y,10+Math.sin(performance.now()/100)*2,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1}
 // Context prompt
 ctx.fillStyle='#e6eddb';ctx.font='700 11px system-ui';ctx.textAlign='center';ctx.globalAlpha=.9;ctx.fillText(nearestAction(),500,623);ctx.globalAlpha=1;
}
function loop(now){if(!running)return;let dt=Math.min(.05,(now-last)/1000);last=now;update(dt);draw();requestAnimationFrame(loop)}
function idle(){if(!running){draw();requestAnimationFrame(idle)}}requestAnimationFrame(idle);updateUI();
</script>
</body>
</html>

