const c=document.querySelector('#game'),g=c.getContext('2d'),W=1000,H=640,$=id=>document.getElementById(id);
const player={x:500,y:588,face:-Math.PI/2,speed:180},people=[{x:255,y:220,n:'Mara',c:'#f0b887'},{x:735,y:220,n:'Theo',c:'#9cc2d3'},{x:260,y:440,n:'June',c:'#d2a7c7'},{x:740,y:440,n:'Eli',c:'#e4d07b'}];
let running=false,won=false,risk=0,saved=0,keys={},target=null,last=0,cooldown=0,clock=0;
// Collision geometry; intentional openings are the interior doors and south exit.
const walls=[{x:120,y:90,w:760,h:14},{x:120,y:90,w:14,h:450},{x:866,y:90,w:14,h:450},{x:120,y:526,w:335,h:14},{x:545,y:526,w:335,h:14},{x:495,y:90,w:10,h:165},{x:495,y:315,w:10,h:211},{x:140,y:305,w:260,h:10},{x:460,y:305,w:40,h:10},{x:500,y:305,w:40,h:10},{x:600,y:305,w:260,h:10},{x:395,y:110,w:10,h:105},{x:395,y:260,w:10,h:45},{x:595,y:110,w:10,h:105},{x:595,y:260,w:10,h:45},{x:395,y:315,w:10,h:100},{x:395,y:460,w:10,h:66},{x:595,y:315,w:10,h:100},{x:595,y:460,w:10,h:66}];
function ui(){let n=people.filter(p=>p.safe).length;$('savedCount').textContent=n;$('saveBar').style.width=n*25+'%';$('riskText').textContent=Math.floor(risk)+'%';$('riskBar').style.width=risk+'%';$('obj1').classList.toggle('done',player.y<540);$('obj2').classList.toggle('done',n>0);$('obj3').classList.toggle('done',won)}
function toast(s){$('message').textContent=s;$('message').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('message').classList.remove('show'),1800)}
function reset(){player.x=500;player.y=588;player.face=-Math.PI/2;people.forEach(p=>{p.safe=false;p.follow=false});risk=0;saved=0;won=false;running=false;target=null;ui()}
