 <script>
+(() => {
+'use strict';
+const canvas=document.getElementById('game'),g=canvas.getContext('2d'),wrap=document.getElementById('canvasWrap');
+const ui={overlay:document.getElementById('overlay'),dialogIcon:document.getElementById('dialogIcon'),dialogKicker:document.getElementById('dialogKicker'),dialogTitle:document.getElementById('dialogTitle'),dialogText:document.getElementById('dialogText'),dialogButton:document.getElementById('dialogButton'),toast:document.getElementById('toast'),count:document.getElementById('objectiveCount'),safe:document.getElementById('safeStat'),progress:document.getElementById('progressFill'),tension:document.getElementById('tensionValue'),tensionFill:document.getElementById('tensionFill'),tensionNote:document.getElementById('tensionNote'),people:document.getElementById('peopleList'),interact:document.getElementById('interactBtn'),interactLabel:document.getElementById('interactLabel'),calm:document.getElementById('calmBtn'),calmHint:document.getElementById('calmHint')};
+const walls=[[120,90,760,14],[120,90,14,450],[866,90,14,450],[120,526,335,14],[545,526,335,14],[495,90,10,165],[495,315,10,211],[140,305,260,10],[460,305,40,10],[500,305,40,10],[600,305,260,10],[395,110,10,105],[395,260,10,45],[595,110,10,105],[595,260,10,45],[395,315,10,100],[395,460,10,66],[595,315,10,100],[595,460,10,66]];
+const residents=[{name:'Maya',x:235,y:205,c:'#e5a56e',safe:false,following:false,panic:30},{name:'Noah',x:755,y:205,c:'#83b5a2',safe:false,following:false,panic:36},{name:'Lena',x:235,y:430,c:'#bd91c2',safe:false,following:false,panic:42},{name:'Eli',x:755,y:430,c:'#d5ca76',safe:false,following:false,panic:34}];
+let player={x:500,y:602,face:-Math.PI/2},trail=[],target=null,keys=new Set(),active=false,ended=false,clock=0,last=0,tension=18,pulseCooldown=0,toastTimer=0,evacuated=0;
+const dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y),clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
+function circleHits(x,y,r){for(const [rx,ry,rw,rh] of walls){const cx=clamp(x,rx,rx+rw),cy=clamp(y,ry,ry+rh);if((x-cx)**2+(y-cy)**2<r*r)return true}return false}
+function showToast(message){ui.toast.textContent=message;ui.toast.classList.add('show');toastTimer=2.2}
+function showDialog(kind,title,text,button){active=false;ui.overlay.hidden=false;ui.dialogIcon.textContent=kind==='win'?'✓':kind==='loss'?'!':'✳';ui.dialogKicker.textContent=kind==='win'?'MISSION COMPLETE':kind==='loss'?'MISSION PAUSED':'FIELD BRIEFING';ui.dialogTitle.textContent=title;ui.dialogText.innerHTML=text;ui.dialogButton.querySelector('.action-label').textContent=button;ui.dialogButton.onclick=()=>{if(kind==='intro')startGame();else resetGame()}}
+function startGame(){ui.overlay.hidden=true;active=true;ended=false;last=performance.now();showToast('Unit ready. Make a steady entry.');requestAnimationFrame(loop);updateUI()}
+function resetGame(){player={x:500,y:602,face:-Math.PI/2};trail=[];target=null;keys.clear();residents.forEach((p,i)=>{p.safe=false;p.following=false;p.panic=[30,36,42,34][i]});tension=18;pulseCooldown=0;evacuated=0;clock=0;startGame()}
+function setTension(value){tension=clamp(value,0,100);if(tension>=100&&!ended){ended=true;showDialog('loss','The room became too tense.','Your team stepped back to reset. Try a slower approach and use calm pulses before escalation peaks.','RETRY MISSION')}}
+function calmPulse(){if(!active||pulseCooldown>0)return;const range=178;tension=Math.max(0,tension-20);residents.forEach(p=>{if(!p.safe)p.panic=Math.max(0,p.panic-38)});pulseCooldown=9;showToast('Calm pulse sent — take a breath.');updateUI();draw()}
+function interact(){if(!active)return;const nearby=residents.filter(p=>!p.safe&&!p.following&&dist(p,player)<43).sort((a,b)=>dist(a,player)-dist(b,player))[0];if(nearby){nearby.following=true;nearby.panic=0;tension=Math.max(0,tension-7);showToast(nearby.name+' is with your unit. Lead them to the exit.');updateUI();return}const followers=residents.filter(p=>p.following);if(followers.length&&dist(player,{x:500,y:565})<54){followers.forEach(p=>{p.following=false;p.safe=true;p.x=500;p.y=565});evacuated+=followers.length;tension=Math.max(0,tension-12*followers.length);showToast(followers.length===1?'Resident safely evacuated.':followers.length+' residents safely evacuated.');if(evacuated===residents.length){ended=true;showDialog('win','Everyone made it out.','Four residents safely evacuated. Your ten-officer team kept the entry calm and brought everyone home.','PLAY AGAIN')}updateUI();return}if(followers.length)showToast('Bring your resident to the green exit.');else showToast('Move closer to a resident, then press E.');}
+function updateUI(){ui.count.textContent=evacuated+' / 4 SAFE';ui.safe.innerHTML=evacuated+' <small style="font-size:11px;color:var(--muted);font-weight:600">/ 4</small>';ui.progress.style.width=(evacuated*25)+'%';ui.tension.textContent=Math.round(tension)+'%';ui.tensionFill.style.width=tension+'%';ui.tensionFill.style.background=tension>70?'linear-gradient(90deg,#efbd69,#ec7968)':'linear-gradient(90deg,#b7d75e,#efbd69)';ui.tensionNote.textContent=tension>75?'Escalation is high. Create space and calm the room now.':tension<25?'Good composure. Keep moving at a steady pace.':'Slow down, give space, and use a calm pulse.';ui.people.innerHTML=residents.map(p=>`<div class="person-row ${p.safe?'safe':''}" style="--dot:${p.c}"><i class="person-dot"></i><span class="person-name">${p.name}</span><span class="person-status">${p.safe?'SAFE':p.following?'WITH UNIT':'WAITING'}</span></div>`).join('');const close=residents.find(p=>!p.safe&&!p.following&&dist(p,player)<43);const carrying=residents.some(p=>p.following);ui.interactLabel.textContent=close?'RESCUE '+close.name:carrying&&dist(player,{x:500,y:565})<54?'EVACUATE':'RESCUE NEAREST';ui.interact.disabled=!active;ui.calmHint.textContent=pulseCooldown>0?'SPACE · '+Math.ceil(pulseCooldown)+'s':'SPACE · READY';ui.calm.disabled=!active||pulseCooldown>0}
+
+function drawRoom(){g.fillStyle='#777b68';g.fillRect(0,0,1000,660);g.fillStyle='#858873';g.fillRect(120,90,760,450);g.fillStyle='#8c8e78';g.fillRect(135,104,730,421);
